// 权限校验
package checker

import (
	"context"
	"encoding/json"
	"log"
	"sync"

	"github.com/pkg/errors"
	"icode.baidu.com/baidu/gdp/extension/gtask"
	"icode.baidu.com/baidu/gdp/logit"

	"icode.baidu.com/baidu/adbiz/fortress-vehicle/library/resource"
	"icode.baidu.com/baidu/adbiz/fortress-vehicle/library/utils"
	"icode.baidu.com/baidu/adbiz/fortress-vehicle/model/service/fortressdatabase"
)

// 权限校验开关 目前阶段先保持关闭，等待联调统一开启
const OpenCheckFlag = true

// PermissionCheckOfCar 车维度的权限校验
func PermissionCheckOfCar(ctx context.Context, regionID string, biz string, carIDs []string) error {
	defer resource.LoggerService.Notice(ctx, "PermissionCheckOfCar", logit.AutoField("regionID", regionID), logit.AutoField("biz", biz), logit.AutoField("carIDs", carIDs))

	if !OpenCheckFlag {
		return nil
	}
	// 增加兜底容错能力，如果上游无法获取区域 id，则不进行权限校验
	if regionID == "" {
		return nil
	}
	if len(carIDs) == 0 {
		return nil
	}

	g := &gtask.Group{
		AllowSomeFail: true,
	}
	var carCPRstMap sync.Map
	for _, carID := range carIDs {
		carID := carID
		g.Go(func() error {
			params := &fortressdatabase.ReqGetCarStatus{
				CarID: carID,
			}
			rstData, err := fortressdatabase.GetOneCarResource(ctx, params)
			if err != nil {
				resource.LoggerService.Warning(ctx, "OldVehicleAutoParkingIn:GetResourceInfoFail", logit.AutoField("err", err))
			}
			if rstData != nil && rstData.Data != nil {
				carCPRstMap.Store(carID, rstData.Data.CPID)
				if rstData.Data.RegionID != regionID {
					resource.LoggerService.Warning(ctx, "PermissionCheckOfCar:Region_auth_check_Fail", logit.AutoField("carID", carID))
					return errors.New("Attention!Auth_check_Fail")
				}
			}
			return nil
		})
	}
	_, _ = g.Wait()

	// 根据 regionID+biz+cpID 获取归属数据范围
	userInfo := utils.GetUserFromCtx(ctx)
	currCPID := userInfo.CpID

	regionByte, _ := json.Marshal([]string{regionID})
	bizByte, _ := json.Marshal([]string{biz})
	belongParams := fortressdatabase.GetBelongCPListReq{
		RegionIDs: string(regionByte),
		Biz:       string(bizByte),
		CPID:      currCPID,
	}

	belongRes, err := fortressdatabase.GetBelongCPList(ctx, belongParams)
	// 如果报错则跳过权限校验
	if err != nil {
		return nil
	}

	availableCPIDs := []int64{}
	if regionRes, ok := belongRes[regionID][biz]; ok {
		availableCPIDs = regionRes.BelongCpIDs
	}

	logit.AddNotice(ctx, logit.AutoField("availableCPIDs", availableCPIDs))
	if len(availableCPIDs) == 0 {
		return errors.New("Attention!Auth_check_Fail")
	}
	checkRes := false
	failCnt := 0
	carCPRstMap.Range(func(key, value interface{}) bool {
		carCPID := int64(0)
		if carCPIDPre, ok := value.(int64); ok {
			carCPID = carCPIDPre
		}

		flag := false
		for _, cpID := range availableCPIDs {
			log.Println(carCPID)
			if carCPID == cpID {
				flag = true
			}
		}
		if !flag {
			failCnt++
		}
		return true
	})
	if failCnt == 0 {
		checkRes = true
	}

	if !checkRes {
		resource.LoggerService.Warning(ctx, "PermissionCheckOfCar:Auth_check_Fail", logit.AutoField("carIDs", carIDs))
		return errors.New("Attention!Auth_check_Fail")
	}
	return nil
}

